INSERT INTO `quiz_questions` VALUES (1,1,'What are the two primary physical components used to build the kinematic chain of a robotic arm?',1,0),(2,1,'Which type of joint permits translational sliding motion along a single linear axis?',1,1),(3,1,'What does \"Degrees of Freedom\" (DOF) represent in robotic manipulation?',1,2),(4,1,'What defines the \"workspace\" of a robotic arm?',1,3),(5,1,'Which factor directly limits the maximum reachable workspace of a robotic arm?',1,4),(6,2,'In 3D Cartesian space, how many parameters are required to fully define both the position and orientation of a rigid body?',1,0),(7,2,'What is calculated during Forward Kinematics?',1,1),(8,2,'What is calculated during Inverse Kinematics (IK)?',1,2),(9,2,'Why might an Inverse Kinematics solver return multiple valid solutions for a single Cartesian pose?',1,3),(10,2,'What occurs when an Inverse Kinematics target is located outside the arm\'s workspace?',1,4),(11,3,'How is motion executed when commanding a robot in \"Joint-Space\"?',1,0),(12,3,'What is a key characteristic of Cartesian-Space motion planning?',1,1),(13,3,'Why is Cartesian-Space motion commonly preferred during the final approach of an object insertion task?',1,2),(14,3,'What is a trajectory in robotic motion control?',1,3),(15,3,'What is a major disadvantage of purely Joint-Space motion when moving near obstacles?',1,4),(16,4,'Which gripper type utilizes two opposing fingers moving in parallel synchronization to clamp flat or box-like objects?',1,0),(17,4,'In what manufacturing scenario is a vacuum/suction gripper typically preferred over a mechanical jaw gripper?',1,1),(18,4,'What advantage do soft/compliant grippers offer over rigid metal grippers?',1,2),(19,4,'Which type of gripper mechanism is restricted strictly to handling ferrous materials?',1,3),(20,4,'Which factor is LEAST critical when selecting an appropriate gripper for a specific application?',1,4),(21,5,'What fundamental equation represents the force due to gravity acting downward on an object of mass \'m\'?',1,0),(22,5,'In friction-based grasping, what role does friction play at the contact points?',1,1),(23,5,'What distinguishes a \"stable grasp\" from an \"unstable grasp\"?',1,2),(24,5,'Why is applying maximum possible grip force generally considered bad practice in robotic manipulation?',1,3),(25,5,'What parameter determines the coefficient of static friction between a gripper finger and an object?',1,4),(26,6,'What two vector summation conditions must be satisfied for a system to be in static equilibrium?',1,0),(27,6,'How is torque (moment) calculated mathematically when a force is applied perpendicular to a lever arm?',1,1),(28,6,'How does fully extending a robot arm horizontally affect the torque required at the shoulder joint to hold a constant payload?',1,2),(29,6,'Why must the weight of the robot\'s own mechanical links be included in static torque analysis?',1,3),(30,6,'Where does the gravitational force of a uniform link act in a static free-body diagram?',1,4),(31,7,'What is the main objective of a position control system in robotics?',1,0),(32,7,'In what situation is pure position control problematic or unsafe?',1,1),(33,7,'What is the primary function of force control during grasping?',1,2),(34,7,'Which control strategy uses feedback from force/torque sensors to yield softly when meeting mechanical resistance?',1,3),(35,7,'In a standard pick-and-place operation, what is the recommended control transition sequence?',1,4),(36,8,'What is the primary purpose of defining a \"pre-grasp\" pose during the approach phase?',1,0),(37,8,'Which phase immediately follows \"Align\" in a standard pick-and-place state sequence?',1,1),(38,8,'Why is vertical \"Lift\" performed before horizontal \"Transfer\" of a grasped workpiece?',1,2),(39,8,'What should every state in a robust pick-and-place state machine explicitly contain?',1,3),(40,8,'What is the final operational step in a complete pick-and-place sequence?',1,4),(41,9,'In a basic 2D two-link planar arm simulation model, how is each link represented geometrically?',1,0),(42,9,'In a Python simulation, what trigonometric formulas compute the end-effector coordinate (x, y) for a 2-link arm with joint angles θ1 and θ2?',1,1),(43,9,'Which popular Python plotting library is commonly used for rendering 2D kinematic arm visualizations and animations?',1,2),(44,9,'In a simulation workflow, how is \"grasping\" typically modeled when hardware contact physics are omitted?',1,3),(45,9,'Why is software simulation recommended before running new control code on physical robot arms?',1,4),(46,10,'What software design pattern is widely used to organize pick-and-place execution logic into distinct operational modes?',1,0),(47,10,'In state machine logic, what triggers the state transition from \"GRASP\" to \"LIFT\"?',1,1),(48,10,'Consider the logic: `if state == \"APPROACH\" and at_pregrasp_pose: state = \"GRASP\"`. What is `at_pregrasp_pose`?',1,2),(49,10,'What is a major software engineering benefit of using a state machine over a long procedural script for robot control?',1,3),(50,10,'Why are safety timeouts critical inside pick-and-place program state loops?',1,4),(51,11,'What defines a robot\'s configuration space (C-space) in a 2D plane?',1,0),(52,11,'What constraint is characteristic of differential drive systems?',1,1),(53,11,'Which of the following limits linear acceleration and deceleration?',1,2),(54,11,'How can a differential drive robot turn in place?',1,3),(55,11,'What does the geometric shape (bounding circle or polygon) of a robot dictate?',1,4),(56,12,'In grid-based map representations, what is continuous floor space discretized into?',1,0),(57,12,'Why is obstacle inflation necessary?',1,1),(58,12,'If a robot has a radius of 0.5 meters and a grid resolution of 0.1 meters per cell, by how many cells are obstacles inflated?',1,2),(59,12,'Which of the following is an inherent limitation of environmental maps?',1,3),(60,12,'What should a planned route through free grid cells always be treated as?',1,4),(61,13,'What do ultrasonic and infrared (IR) sensors measure for short-range distance estimation?',1,0),(62,13,'What is a primary limitation of ultrasonic and infrared sensors?',1,1),(63,13,'What do LiDAR units use to construct dense point clouds of surroundings?',1,2),(64,13,'Which filter is mentioned for accumulating sensor data over multiple sampling cycles with confidence weights?',1,3),(65,13,'How should a spurious echo from a dust particle be handled by the navigation system?',1,4),(66,14,'What triggers an immediate stop command in reactive obstacle avoidance?',1,0),(67,14,'Which of the following is a common reactive obstacle avoidance strategy?',1,1),(68,14,'What is a primary strength of reactive obstacle avoidance strategies?',1,2),(69,14,'What is a major limitation of purely reactive controllers?',1,3),(70,14,'Why must optimal robotic architectures combine reactive behaviors with global path planning?',1,4),(71,15,'How does Breadth-First Search (BFS) explore grid cells?',1,0),(72,15,'What is a major drawback of Breadth-First Search in robotics?',1,1),(73,15,'What does Dijkstra\'s algorithm evaluate nodes based on?',1,2),(74,15,'What does the A* (A-star) search evaluation function f(n) consist of?',1,3),(75,15,'How is the heuristic estimate h(n) often calculated for grid-based robotics in A*?',1,4),(76,16,'What does a geometric path dictate in robotics engineering?',1,0),(77,16,'What does trajectory planning add to a geometric path?',1,1),(78,16,'Which physical limitations are integrated during trajectory planning?',1,2),(79,16,'Why is optimal navigation route calculation fundamentally a time-optimization problem?',1,3),(80,16,'What velocity profiles are typically generated to ensure smooth trajectory execution?',1,4),(81,17,'What must an autonomous mobile robot analyze candidate paths for during minimum-time navigation?',1,0),(82,17,'How is the turning velocity v_turn constrained around sharp 