INSERT INTO `topics` VALUES (1,1,NULL,'L15 - Robotic Manipulation and Grasping','L15 - Robotic Manipulation and Grasping','<p data-path-to-node=\"2\" style=\"--animation-duration: 644ms;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\" id=\"p-rc_d214fcbd66762efb-19\"><span data-path-to-node=\"2,0\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Robotic manipulation and grasping form the fundamental foundation of physical interaction between autonomous systems and the physical world</span><span data-path-to-node=\"2,1\" class=\"\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"2,2\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. At its core, this discipline explores how a robotic arm navigates 3D space to reach for, grip, securely hold, relocate, and release target objects with accuracy and stability</span><span data-path-to-node=\"2,3\" class=\"\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"2,4\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. While these actions are second nature to humans, enabling a machine to interact with everyday items requires seamless coordination between computer vision, motion planning, sensor feedback, and precise mechanical control</span><span data-path-to-node=\"2,5\" class=\"\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"2,6\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"Spline Sans&quot;; margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   </sources-carousel-inline></p><p data-path-to-node=\"3\" id=\"p-rc_d214fcbd66762efb-20\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"3,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">The complexity of robotic manipulation lies in the diversity of environments and objects a system encounters</span><span data-path-to-node=\"3,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"3,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. A robot must dynamic adjust its grip force, wrist orientation, and trajectory depending on whether it is handling rigid industrial tools, delicate glassware, or soft, deformable objects</span><span data-path-to-node=\"3,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"3,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Modern algorithms utilize contact dynamics, force sensing, and spatial kinematics to ensure that the mechanical end-effector maintains sufficient control without causing damage or dropping the item during movement</span><span data-path-to-node=\"3,5\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"3,6\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><p data-path-to-node=\"4\" id=\"p-rc_d214fcbd66762efb-21\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"4,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">As automation expands beyond fixed industrial assembly lines into unpredictable real-world environments—such as e-commerce fulfillment centers, surgical operating rooms, and domestic service—mastering manipulation and grasping becomes essential</span><span data-path-to-node=\"4,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"4,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Understanding these core mechanics enables engineers to design smarter robotic systems capable of executing versatile, high-precision tasks alongside humans safely and efficiently</span><span data-path-to-node=\"4,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"4,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.<br></span></p>',24,16,'https://www.youtube.com/watch?v=jAhpRolF-zg',NULL,'top','2026-10-21 10:57:18'),(2,1,1,'L15.1 — Robotic Arm Structure','L15.1 — Robotic Arm Structure','\r\n<p data-path-to-node=\"3\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">The physical architecture of a robotic manipulator serves as the foundational skeleton that dictates every kinematic and dynamic capability available to the system.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> At its core,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> an industrial or service robotic arm is structured as an open or closed kinematic chain composed of rigid structural bodies known as </span><b data-path-to-node=\"3\" data-index-in-node=\"311\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">links</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> interconnected by moveable mechanical connections called </span><b data-path-to-node=\"3\" data-index-in-node=\"375\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">joints</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span></p><ul data-path-to-node=\"4\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"4,0,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"4,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Links and Structural Segments:</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> Links act as the rigid members transmitting forces and moments from one joint to the next.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> The material composition,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> cross-sectional geometry,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> and mass distribution of these links heavily influence the arm\'s structural rigidity,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> natural frequency,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> and payload-to-weight ratio.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> High-performance arms often utilize carbon fiber composites or aerospace-grade aluminum alloys to minimize inertia while maximizing structural stiffness.</span></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"4,1,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"4,1,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Joint Classifications:</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> Joints are broadly categorized based on their mechanical degree of freedom.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> </span><b data-path-to-node=\"4,1,0\" data-index-in-node=\"99\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Revolute joints</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> permit rotational motion about a single fixed axis,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> closely mimicking human anatomical joints like the shoulder,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> elbow,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> or knuckle.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> Conversely,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> </span><b data-path-to-node=\"4,1,0\" data-index-in-node=\"259\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">prismatic joints</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> facilitate linear sliding motion along a single directional axis,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> operating similarly to a hydraulic piston or a telescoping track.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> By chaining these joints together,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> engineers define the </span><b data-path-to-node=\"4,1,0\" data-index-in-node=\"464\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Degrees of Freedom (DOF)</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> of the system.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> A minimum of 6 DOF is typically required in general-purpose robotics to position and orient an end-effector arbitrarily within three-dimensional Cartesian space (3 dimensions for spatial position </span><span class=\"math-inline\" data-math=\"x, y, z\" data-index-in-node=\"700\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">$x, y, z$</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> and 3 dimensions for rotational orientation:</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> roll,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> pitch,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> yaw).</span></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"4,2,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"4,2,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Workspace Constraints and Envelopes:</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> The workspace defines the total spatial volume swept by the robot\'s end-effector across all possible joint configurations.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> This geometric envelope is heavily constrained by physical link lengths,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> mechanical joint travel stops (e.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">g.,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> internal wiring limits or physical physical blocks),</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> and self-collision avoidance zones where parts of the robot would otherwise strike each other.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> Furthermore,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> environmental obstacles in the immediate workspace restrict the operational volume further,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> requiring sophisticated collision-free trajectory planning.</span></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"4,3,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"4,3,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">End-Effector Integration:</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> The terminal link of the kinematic chain terminates in a mounting flange designed to accept the </span><b data-path-to-node=\"4,3,0\" data-index-in-node=\"122\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">end-effector</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> Whether configured as an adaptive multi-fingered hand,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> a parallel-jaw mechanism,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> a vacuum suction array,</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> or a specialized manufacturing tool (such as a welding gun or laser cutter),</span><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"> the end-effector is selected and optimized specifically to match the physical properties of the target payload and the requirements of the task.</span></p></li></ul>\n<!-- lesson15-16-content-expansion-v1 -->\n<p><strong>Structural Load Paths:</strong> Payload forces travel from the tool through the wrist, links, and joints into the base and mounting surface. Understanding this load path helps engineers select link materials, bearings, and fasteners that can withstand both static loads and repeated motion.</p>\n<p><strong>Joint Limits and Singularities:</strong> Each joint has a safe operating range, and some configurations make the arm lose useful motion in a particular direction. A controller should check limits and avoid singular configurations because small tool movements there can require very large joint movements.</p>\n<p><strong>Calibration:</strong> The mathematical model must agree with the physical arm. Home switches, encoder offsets, link-length measurements, and tool-center-point calibration reduce the difference between the commanded pose and the actual end-effector pose.</p>',24,16,'https://www.youtube.com/watch?v=ZXDhCecxTU0',NULL,'top','2026-10-21 11:23:53'),(3,1,1,'L15.2 — Position and Orientation','L15.2 — Position and Orientation','<p data-path-to-node=\"7\" id=\"p-rc_8e7fb282b1ba2638-227\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"7,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Precise manipulation requires defining both where the end-effector is located in physical space and how it is rotated relative to a reference coordinate system</span><span data-path-to-node=\"7,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"7,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><ul data-path-to-node=\"8\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"8,0,0\" id=\"p-rc_8e7fb282b1ba2638-228\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"8,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"8,0,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Coordinates &amp; Reference Frames</b>: Positions are typically expressed in Cartesian coordinates <span class=\"math-inline\" data-math=\"(x, y, z)\" data-index-in-node=\"91\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">(x, y, z)</span> relative to a global <i data-path-to-node=\"8,0,0,0\" data-index-in-node=\"122\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">base frame</i> fixed to the robot\'s mounting base</span><span data-path-to-node=\"8,0,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,0,0,2\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. The <i data-path-to-node=\"8,0,0,2\" data-index-in-node=\"6\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">tool frame</i> (or end-effector frame) travels dynamically with the gripper tip. Maintaining consistent units and reference frame definitions is critical for accurate path execution</span><span data-path-to-node=\"8,0,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,0,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"8,1,0\" id=\"p-rc_8e7fb282b1ba2638-229\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"8,1,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"8,1,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Kinematics Overview</b>: Kinematics studies motion without analyzing the underlying forces causing it</span><span data-path-to-node=\"8,1,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><ul data-path-to-node=\"8,1,1\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"8,1,1,0,0\" id=\"p-rc_8e7fb282b1ba2638-230\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"8,1,1,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"8,1,1,0,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Forward Kinematics</b>: Given a known set of joint angles (<span class=\"math-inline\" data-math=\"\\theta_1, \\theta_2, \\dots\" data-index-in-node=\"55\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">θ₁, θ₂, \\dots</span>), forward kinematics computes the resulting position and orientation of the tool frame</span><span data-path-to-node=\"8,1,1,0,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,1,1,0,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"8,1,1,1,0\" id=\"p-rc_8e7fb282b1ba2638-231\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"8,1,1,1,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"8,1,1,1,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Inverse Kinematics (IK)</b>: Given a desired target position and orientation for the tool, inverse kinematics calculates the required joint angles to achieve that pose</span><span data-path-to-node=\"8,1,1,1,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,1,1,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Depending on the arm geometry, target locations may yield no solutions (unreachable), a single solution, or multiple valid configurations (such as \"elbow-up\" vs. \"elbow-down\")</span><span data-path-to-node=\"8,1,1,1,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,1,1,1,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li></ul></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"8,2,0\" id=\"p-rc_8e7fb282b1ba2638-232\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"8,2,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><i data-path-to-node=\"8,2,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Safety Check</i>: Always verify whether a target pose is reachable within the workspace before commanding joint actuators to move</span><span data-path-to-node=\"8,2,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"8,2,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   </sources-carousel-inline></p></li></ul>\r\n<span data-path-to-node=\"6,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Kinematics allows engineers to map coordinate frames between the fixed base and the moving end-effector</span><span data-path-to-node=\"6,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"6,2\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Forward kinematics computes tool position from joint angles, while inverse kinematics calculates required joint angles for a target <span class=\"math-inline\" data-math=\"(x, y, z)\" data-index-in-node=\"134\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">(x, y, z)</span> pose</span><span data-path-to-node=\"6,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"6,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span>\r\n\r\n<img src=\"http://localhost:5001/uploads/c945d261-ffda-484b-9b25-75989abe8d2c.png\" alt=\"Pasted image\">\n<!-- lesson15-16-content-expansion-v1 -->\n<p><strong>Pose Representation:</strong> A pose combines a position vector with an orientation representation such as roll-pitch-yaw angles, a rotation matrix, or a quaternion. The chosen representation should be interpreted consistently so that rotations are not silently applied in the wrong order.</p>\n<p><strong>Frame Transformations:</strong> A target measured by a camera or fixture must be transformed into the robot base frame before inverse kinematics is used. Chaining transforms between the base, tool, sensor, and object frames makes the source of each coordinate explicit.</p>\n<p><strong>Orientation Tolerance:</strong> A placement can have an acceptable position error but still fail if the tool is rotated incorrectly. Practical motion planners therefore define separate position and orientation tolerances and verify both before releasing a payload.</p>',24,16,'https://www.youtube.com/watch?v=1-FJhmey7vk',NULL,'top','2026-10-21 11:44:25'),(4,1,1,'L15.3 — Joint-space and Cartesian Motion','L15.3 — Joint-space and Cartesian Motion','\r\n<p data-path-to-node=\"11\" id=\"p-rc_8e7fb282b1ba2638-233\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"11,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">When planning how a robotic arm transitions from a start pose to a target destination, engineers utilize two distinct motion description spaces</span><span data-path-to-node=\"11,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"11,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">:</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><ul data-path-to-node=\"12\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"12,0,0\" id=\"p-rc_8e7fb282b1ba2638-234\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"12,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"12,0,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Joint-Space Motion</b>: Commands are issued directly to individual joint actuators (e.g., specifying target angles for each motor)</span><span data-path-to-node=\"12,0,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"12,0,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. This approach is computationally efficient and straightforward for low-level joint controllers. However, the physical path traced by the end-effector through Cartesian space tends to curve rather than follow a straight line</span><span data-path-to-node=\"12,0,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"12,0,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"12,1,0\" id=\"p-rc_8e7fb282b1ba2638-235\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"12,1,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"12,1,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Cartesian-Space Motion</b>: Specifies the exact geometric path the gripper must follow through <span class=\"math-inline\" data-math=\"x, y, z\" data-index-in-node=\"91\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">$x, y, z$</span> space (such as a linear approach or a straight-line withdrawal)</span><span data-path-to-node=\"12,1,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"12,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. This is essential for delicate operations like insertion tasks. It requires continuous, real-time conversion from tool positions to joint motion via inverse kinematics</span><span data-path-to-node=\"12,1,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"12,1,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"12,2,0\" id=\"p-rc_8e7fb282b1ba2638-236\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"12,2,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"12,2,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Trajectory Planning</b>: A trajectory combines path geometry with a planned sequence of positions over time, incorporating strict velocity, acceleration, and deceleration limits to prevent mechanical shock and vibration</span><span data-path-to-node=\"12,2,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"12,2,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   \r\n<h3 data-path-to-node=\"9\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><img src=\"http://localhost:5001/uploads/666fc393-14e9-45ac-b855-04abd0e1e786.png\" alt=\"Pasted image\"></h3></sources-carousel-inline></p></li></ul>\n<!-- lesson15-16-content-expansion-v1 -->\n<p><strong>Choosing a Motion Space:</strong> Joint-space motion is often shorter to compute and can keep every actuator within its limits, while Cartesian motion gives better control over the tool path. The task determines which priority matters more: actuator efficiency, geometric precision, or collision clearance.</p>\n<p><strong>Interpolation Timing:</strong> Position interpolation alone does not guarantee safe motion. A time-scaling function should provide smooth velocity and acceleration, with zero or controlled endpoint velocity when the arm approaches a grasp or placement pose.</p>\n<p><strong>Jacobian Connection:</strong> The Jacobian maps joint velocities to end-effector velocity. Monitoring its condition helps identify near-singular poses and lets a controller reduce speed or choose an alternative configuration before tracking quality deteriorates.</p>',24,16,'https://www.youtube.com/watch?v=iDiDLZX2Nmg',NULL,'top','2026-10-21 12:26:38'),(5,1,1,'L15.4 — Gripper Mechanisms','L15.4 — Gripper Mechanisms','\r\n<p data-path-to-node=\"15\" id=\"p-rc_8e7fb282b1ba2638-237\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"15,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">The gripper mechanism is the critical interface between the robot and the physical object</span><span data-path-to-node=\"15,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"15,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Selecting the appropriate end-effector requires matching its design to the task requirements</span><span data-path-to-node=\"15,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"15,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><ul data-path-to-node=\"16\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"16,0,0\" id=\"p-rc_8e7fb282b1ba2638-238\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"16,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"16,0,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Parallel-Jaw Grippers</b>: Feature two opposing jaws that move synchronously inward and outward</span><span data-path-to-node=\"16,0,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"16,0,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. They are robust, reliable, and exceptionally useful for handling boxes, cubes, and rigid industrial parts with parallel surfaces</span><span data-path-to-node=\"16,0,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"16,0,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. The grip opening range must be carefully sized to fit the target object</span><span data-path-to-node=\"16,0,0,5\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"16,0,0,6\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"16,1,0\" id=\"p-rc_8e7fb282b1ba2638-239\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"16,1,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"16,1,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Multi-Finger Hands</b>: Offer multiple contact points and enhanced flexibility, allowing them to adapt to irregular or complex shapes, though control architectures are significantly more complex</span><span data-path-to-node=\"16,1,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"16,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"16,2,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"16,2,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Alternative Options</b><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">:</span></p><ul data-path-to-node=\"16,2,1\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"16,2,1,0,0\" id=\"p-rc_8e7fb282b1ba2638-240\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"16,2,1,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"16,2,1,0,0,