-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"32,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"32,2,0\" id=\"p-rc_8e7fb282b1ba2638-261\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"32,2,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"32,2,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Grasp</b>: Close the gripper mechanism and confirm positive contact</span><span data-path-to-node=\"32,2,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-sta